-- 부트 것을 하나 연다

// JacksonAutoConfiguration 안쪽
@Bean
@Primary
@ConditionalOnMissingBean
ObjectMapper jacksonObjectMapper(Jackson2ObjectMapperBuilder builder) {
    return builder.createXmlMapper(false).build();
}

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A2 'JacksonAutoConfiguration.*jacksonObjectMapper matched' | head -3
   JacksonAutoConfiguration$JacksonObjectMapperConfiguration#jacksonObjectMapper matched:
      - @ConditionalOnMissingBean (types: com.fasterxml.jackson.databind.ObjectMapper;
        SearchStrategy: all) did not find any beans

$ curl -s 'localhost:8080/beans/def?name=jacksonObjectMapper'
출처: ...JacksonAutoConfiguration$JacksonObjectMapperConfiguration


-- 내가 만든다

@Configuration
public class MyJacksonConfig {
    @Bean
    public ObjectMapper objectMapper() {
        var om = new ObjectMapper();
        om.setSerializationInclusion(JsonInclude.Include.NON_NULL);
        return om;
    }
}

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A2 'jacksonObjectMapper:' | head -3
   JacksonAutoConfiguration$JacksonObjectMapperConfiguration#jacksonObjectMapper:
      Did not match:
         - @ConditionalOnMissingBean found beans of type
           'com.fasterxml.jackson.databind.ObjectMapper' objectMapper

$ curl -s 'localhost:8080/beans/names?type=ObjectMapper'
objectMapper

$ curl -s 'localhost:8080/beans/def?name=objectMapper'
출처: study.boot.MyJacksonConfig

--   내 것 이름이 조건 메시지에 적혀 있다
--   빈은 하나뿐이다


-- 실제로 응답이 바뀐다

@GetMapping("/item")
Item item() { return new Item("연필", null); }

record Item(String name, String memo) {}

// 부트 기본일 때
$ curl -s localhost:8080/item
{"name":"연필","memo":null}

// 내 빈이 있을 때
$ curl -s localhost:8080/item
{"name":"연필"}

--   같은 컨트롤러인데 응답이 다르다


-- 끄는 것과 다르다

@SpringBootApplication(exclude = JacksonAutoConfiguration.class)

$ curl -s -o /dev/null -w '%{http_code}\n' localhost:8080/item
500
$ ./gradlew bootRun 2>&1 | grep -i 'No converter' | head -1
No converter for [class study.boot.Item] with preset Content-Type 'null'

--   통째로 빼면 다른 빈들까지 사라진다
--   대체와 제외는 다른 자리다


-- 내가 하나 만든다

package study.lib;

@AutoConfiguration
public class GreeterAutoConfiguration {
    @Bean
    @ConditionalOnMissingBean
    public Greeter greeter() { return name -> "안녕 " + name; }
}

public interface Greeter { String greet(String name); }

$ curl -s 'localhost:8080/greet?name=철수'
안녕 철수

$ curl -s 'localhost:8080/beans/def?name=greeter'
출처: study.lib.GreeterAutoConfiguration


-- 내 것을 넣으면

@Configuration
class MyGreeterConfig {
    @Bean Greeter greeter() { return name -> name + "님 반갑습니다"; }
}

$ curl -s 'localhost:8080/greet?name=철수'
철수님 반갑습니다

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A2 'GreeterAutoConfiguration#greeter:' | head -3
   GreeterAutoConfiguration#greeter:
      Did not match:
         - @ConditionalOnMissingBean found beans of type
           'study.lib.Greeter' greeter

$ curl -s 'localhost:8080/beans/names?type=Greeter'
greeter

--   이름이 같아도 하나뿐이다


-- 이름을 다르게 해도 진다

@Bean Greeter politeGreeter() { return name -> name + "님"; }

$ curl -s 'localhost:8080/beans/names?type=Greeter'
politeGreeter

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A2 'GreeterAutoConfiguration#greeter:' | tail -2
         - @ConditionalOnMissingBean found beans of type
           'study.lib.Greeter' politeGreeter

--   타입으로 보니 이름이 달라도 걸린다


-- 타입이 넓으면 엉뚱한 게 걸린다

@Bean
@ConditionalOnMissingBean
public Executor taskExecutor() { return Executors.newFixedThreadPool(4); }

// 어딘가에 이런 게 있으면
@Bean Executor mailExecutor() { return Executors.newSingleThreadExecutor(); }

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A2 'taskExecutor:' | tail -2
         - @ConditionalOnMissingBean found beans of type
           'java.util.concurrent.Executor' mailExecutor

$ curl -s 'localhost:8080/beans/names?type=Executor'
mailExecutor

--   전혀 다른 용도인데 걸렸다
--   이름으로 좁혀야 한다


-- 이름으로 좁힌다

@Bean
@ConditionalOnMissingBean(name = "taskExecutor")
public Executor taskExecutor() { return Executors.newFixedThreadPool(4); }

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -A2 'taskExecutor matched' | head -3
   MyAsyncAutoConfiguration#taskExecutor matched:
      - @ConditionalOnMissingBean (names: taskExecutor; SearchStrategy: all)
        did not find any beans

$ curl -s 'localhost:8080/beans/names?type=Executor'
mailExecutor,taskExecutor

--   둘 다 산다


-- 값으로도 적을 수 있다

@Bean
@ConditionalOnMissingBean(Greeter.class)
public Greeter greeter() { ... }

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep 'GreeterAutoConfiguration#greeter' | head -1
   GreeterAutoConfiguration#greeter matched

