-- 늦게 등록하면 못 본다

@Component
class LateRegistrar implements BeanDefinitionRegistryPostProcessor {
    public void postProcessBeanDefinitionRegistry(BeanDefinitionRegistry r) {
        r.registerBeanDefinition("lateGreeter",
            BeanDefinitionBuilder.genericBeanDefinition(LateGreeter.class)
                .getBeanDefinition());
    }
}

$ ./gradlew bootRun 2>&1 | head -4
***************************
APPLICATION FAILED TO START
***************************
required a single bean, but 2 were found:
	- greeter: ...GreeterAutoConfiguration
	- lateGreeter: ...

