-- 싱글턴을 직접 넣어도 못 본다

ctx.getBeanFactory().registerSingleton("runtimeGreeter", (Greeter) n -> "런타임");

$ ./gradlew bootRun --args='--debug' 2>&1 \
    | grep -c 'GreeterAutoConfiguration#greeter matched'
1

$ curl -s 'localhost:8080/beans/names?type=Greeter'
greeter,runtimeGreeter

